/* Live Phase 1 portal. All authorisation and balances are enforced by PostgreSQL. */
const portalLegacyRender=render;
const portal={booting:true,configured:false,connectionError:'',client:null,user:null,profile:null,authMode:'login',authMessage:'',authError:'',loading:false,error:'',policies:[],ledger:[],receipts:[],paymentSummary:{},summary:{},status:'All',search:'',limit:50,hasMore:false,view:'home',mobileOpen:false,sidebarClosed:false,busy:false,recovery:false,channel:null,poll:null,refreshTimer:null,refreshVersion:0};
const portalRoutes=['policyportal','login','register','partner','mypolicies','wallet','admin','admin-policies','admin-ledger'];
const pe=esc;
const portalEntry=PortalCore.workspace(location.pathname,location.hash);
function portalWorkspaceUrl(role){return role==='admin'?'/admin#admin':'/partner#partner'}
function portalWorkspaceMismatch(){return portal.profile&&portal.profile.role!==portalEntry.role}
function portalWrongWorkspace(){return '<main class="portal-auth-wrap"><section class="portal-auth-card"><img class="portal-auth-logo" src="/sigma0nine-logo.png" alt="Sigma0Nine"><span class="eyebrow">'+pe(portalEntry.role.toUpperCase())+' ACCESS</span><h1>This account belongs to the '+pe(portal.profile.role)+' workspace.</h1><p>You signed in as '+pe(portal.profile.email)+'. This page requires a '+pe(portalEntry.role)+' account. Your access has not changed.</p><a class="primary" href="'+portalWorkspaceUrl(portal.profile.role)+'">Open my workspace</a><div class="actions">'+portalButton('Use a different account','portalSignOut()','logout')+'</div></section></main>'}

function portalButton(label,handler,icon='',primary=false){return `<button type="button" class="${primary?'primary':''}" onclick="${pe(handler)}">${icon?I(icon):''}${pe(label)}</button>`}
function portalDate(value){return value?new Date(value).toLocaleString('en-IN',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—'}
function portalStatus(value){return `<span class="portal-status status-${pe(String(value).toLowerCase())}">${pe(value==='Uploading'?'Upload incomplete':value)}</span>`}
function portalInitial(name){return pe(String(name||'Partner').trim().split(/\s+/).slice(0,2).map(s=>s[0]||'').join('').toUpperCase())}
function portalNotify(text){toast(text)}
function portalInlineError(text){return text?`<div class="portal-alert" role="alert">${pe(text)}</div>`:''}
function portalCreditFor(p){let row=p.sigma_ledger;return Array.isArray(row)?row[0]:row}
function portalOwner(p){return p.owner_profile||portal.profile||{full_name:'Partner',email:''}}
function portalModeAdmin(){return portal.profile?.role==='admin'}
function portalRoute(view){if(['quotes','nivaquote','savedquotes','network'].includes(view))view='home';if(view==='marketing')view='brochures';portal.view=view;portal.mobileOpen=false;portal.search='';portal.status='All';portal.limit=50;const hash=view==='home'?(portalModeAdmin()?'admin':'partner'):view==='policies'?(portalModeAdmin()?'admin-policies':'mypolicies'):view==='wallet'?(portalModeAdmin()?'admin-ledger':'wallet'):view;history.replaceState(null,'','#'+hash);current=view;portalRender();window.scrollTo(0,0)}

render=function(){if(portal.booting||portal.connectionError||portal.configured||portalRoutes.includes(current))return portalRender();portalLegacyRender();const navNode=document.querySelector('.nav');navNode?.insertAdjacentHTML('afterbegin',`<button onclick="portalOpen()" title="Live policy portal">${I('shield')}Policy portal</button>`)};
function portalOpen(){current='policyportal';location.hash='policyportal';portalRender()}

function portalLoading(){return `<main class="portal-auth-wrap"><div class="portal-loading"><img src="sigma0nine-logo.png" alt="Sigma0Nine"><div class="portal-spinner"></div><h2>Opening your secure workspace</h2><p>Checking the account connection…</p></div></main>`}
function portalSetup(){return `<main class="portal-auth-wrap"><section class="portal-auth-card portal-setup"><img class="portal-auth-logo" src="sigma0nine-logo.png" alt="Sigma0Nine"><span class="eyebrow">PHASE 1 · POLICY PORTAL</span><h1>One last connection<br>before we go live.</h1><p>The partner login, private upload, admin approval and credit workflow is built. A shared database has not been connected to this deployment yet.</p><div class="portal-setup-list"><span>${I('check')}Login & role-based access</span><span>${I('check')}Private policy documents</span><span>${I('check')}Admin approval & one-time credits</span><span>${I('clock')}Database connection pending</span></div>${portalInlineError(portal.connectionError)}<div class="actions">${portalButton('Check connection again','portalBoot()','renew',true)}${!portal.configured?portalButton('Existing workspace','portalExitSetup()','grid'):''}</div><p class="subtle">Setup needs your Supabase project URL, publishable key and the supplied SQL migration. No fake login or local-only admin balance is used here.</p></section></main>`}
function portalExitSetup(){if(portal.configured)return;portal.connectionError='';portal.booting=false;current='dashboard';location.hash='dashboard';render()}

function portalSetAuthMode(mode){portal.authMode=mode;portal.authMessage='';portal.authError='';portalRender()}
function portalError(error){let text=error?.message||'Something went wrong. Please try again.';if(/email.*rate limit/i.test(text))return 'Email sending limit reached. Sign in with your existing password, or try the email link later.';if(/relation .* does not exist|schema cache|PGRST205/.test(text))return 'Database setup is incomplete. Apply the Phase 1 SQL migration in your Supabase project.';if(/Failed to fetch|NetworkError/i.test(text))return 'Could not reach the service. Check your connection and try again.';return text.slice(0,400)}

async function portalBoot(){const wanted=PortalCore.workspace(location.pathname,location.hash);if(location.pathname!==wanted.path){location.replace(wanted.path+location.search+location.hash);return}if(new URLSearchParams(location.search).get('code')==='1')portal.authMode='invite';portal.booting=true;portal.connectionError='';portalRender();try{const response=await fetch('/api/config',{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('The account service configuration could not be loaded');const config=await response.json();portal.configured=config.configured===true;portal.emailOtpEnabled=config.emailOtpEnabled===true;if(!portal.configured){portal.booting=false;render();return}if(!globalThis.SigmaSupabase?.createClient)throw Error('The sign-in client could not be loaded. Refresh the page.');portal.client=portal.client||SigmaSupabase.createClient(config.url,config.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,...PortalCore.authOptions(portalEntry,window.sessionStorage,window.localStorage,()=>crypto.randomUUID())}});if(!portal.authSubscription){portal.authSubscription=portal.client.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'||new URLSearchParams(location.search).get('invite')==='1'){portal.recovery=true;portal.authMode='reset'}setTimeout(()=>{if(!portal.busy)portalHandleSession(session).catch(e=>{portal.error=portalError(e);portalRender()})},0)}).data.subscription}const {data,error}=await portal.client.auth.getSession();if(error)throw error;if(data.session&&new URLSearchParams(location.search).get('invite')==='1'){portal.recovery=true;portal.authMode='reset'}await portalHandleSession(data.session)}catch(e){portal.connectionError=portalError(e)}finally{portal.booting=false;render()}}
let portalSessionSerial=0;
async function portalHandleSession(session){const serial=++portalSessionSerial;if(session?.user?.id&&portal.user?.id!==session.user.id){portal.refreshVersion++;portal.user=null;portal.profile=null;portal.policies=[];portal.ledger=[];portal.paymentSummary={};portal.summary={};if(typeof portalResetBusiness==='function')portalResetBusiness();portalStopSync();portalRender()}if(!session){if(typeof portalResetBusiness==='function')portalResetBusiness();portal.user=null;portal.profile=null;portal.policies=[];portal.ledger=[];portal.paymentSummary={};portal.summary={};portalStopSync();portalRender();return}const {data,error}=await portal.client.auth.getUser();if(error||!data.user){portal.user=null;portal.profile=null;throw error||Error('Please sign in again')}if(serial!==portalSessionSerial)return;portal.user=data.user;const profile=await portal.client.from('sigma_profiles').select('id,full_name,email,phone,address,avatar_path,managing_admin,role').eq('id',data.user.id).single();if(profile.error)throw profile.error;if(serial!==portalSessionSerial)return;portal.profile=profile.data;if(typeof portalLoadAvatar==='function')await portalLoadAvatar();if(typeof portalLoadBusiness==='function')await portalLoadBusiness(data.user.id);if(serial!==portalSessionSerial)return;portal.view=['wallet','admin-ledger'].includes(location.hash.slice(1))?'wallet':['mypolicies','admin-policies'].includes(location.hash.slice(1))?'policies':'home';if(typeof portalBusinessRoute==='function')portal.view=portalBusinessRoute();await portalRefresh();if(serial!==portalSessionSerial)return;portalStartSync(session);portalRender()}
function portalStopSync(){if(portal.channel&&portal.client)portal.client.removeChannel(portal.channel);portal.channel=null;clearInterval(portal.poll);clearTimeout(portal.refreshTimer);portal.poll=null}
function portalStartSync(session){portalStopSync();portal.client.realtime.setAuth(session.access_token);portal.channel=portal.client.channel('sigma-portal-'+portal.user.id).on('postgres_changes',{event:'*',schema:'public',table:'sigma_policies'},portalScheduleRefresh).on('postgres_changes',{event:'INSERT',schema:'public',table:'sigma_ledger'},portalScheduleRefresh).on('postgres_changes',{event:'INSERT',schema:'public',table:'sigma_payment_receipts'},portalScheduleRefresh).subscribe();portal.poll=setInterval(()=>{if(document.visibilityState==='visible'&&!portal.busy)portalRefresh(true)},20000)}
function portalScheduleRefresh(){clearTimeout(portal.refreshTimer);portal.refreshTimer=setTimeout(()=>portalRefresh(true),300)}
async function portalRefresh(silent=false){if(!portal.user||!portal.profile)return;const version=++portal.refreshVersion;portal.loading=!silent;portal.error='';if(!silent)portalRender();try{const [policies,ledger,summary,payments]=await Promise.all([portal.client.from('sigma_policies').select('*,owner_profile:sigma_profiles!sigma_policies_owner_id_fkey(id,full_name,email),uploader_profile:sigma_profiles!sigma_policies_uploaded_by_fkey(full_name,email),sigma_ledger(id,owner_id,policy_id,points,amount_paise,note,created_at,sigma_payment_receipts(*))').order('created_at',{ascending:false}).range(0,portal.limit),portal.client.from('sigma_ledger').select('*,sigma_payment_receipts(*),owner_profile:sigma_profiles!sigma_ledger_owner_id_fkey(full_name,email),policy:sigma_policies(customer_name,product,policy_number)').order('created_at',{ascending:false}).range(0,portal.limit),portal.client.rpc('sigma_portal_summary'),portal.client.rpc('sigma_payment_summary')]);for(const result of [policies,ledger,summary,payments])if(result.error)throw result.error;if(version!==portal.refreshVersion)return;portal.hasMore=(policies.data?.length||0)>portal.limit;portal.ledgerHasMore=(ledger.data?.length||0)>portal.limit;portal.policies=(policies.data||[]).slice(0,portal.limit);portal.ledger=(ledger.data||[]).slice(0,portal.limit);portal.summary=summary.data||{};portal.paymentSummary=payments.data||{};if(typeof portalMirrorPolicies==='function')portalMirrorPolicies();if(typeof portalSyncBusiness==='function')await portalSyncBusiness();if(portal.view==='form-enquiries'&&typeof portalLoadEnquiries==='function')await portalLoadEnquiries()}catch(e){if(version===portal.refreshVersion)portal.error=portalError(e)}finally{if(version===portal.refreshVersion){portal.loading=false;if(!silent||typeof portalPageIsEditing!=='function'||!portalPageIsEditing())portalRender()}}}
async function portalSignOut(){if(typeof portalFlushBusiness==='function'&&business.dirty&&!await portalFlushBusiness()){toast('Workspace changes are unsaved. Download a backup or retry before signing out.');return}if(typeof portalResetBusiness==='function')portalResetBusiness();portalStopSync();portalSessionSerial++;portal.refreshVersion++;portal.user=null;portal.profile=null;portal.policies=[];portal.ledger=[];portal.paymentSummary={};portal.summary={};portal.error='';portal.authError='';portal.busy=false;closeModal();const result=await portal.client.auth.signOut({scope:'local'});if(result.error)portal.authError=portalError(result.error);portalRender()}

function portalRender(){const root=document.querySelector('#app');if(!root)return;root.classList.toggle('sidebar-collapsed',portal.sidebarClosed);document.title=(portal.profile?portalModeAdmin()?'Admin':'Partner':'Sign in')+' — Sigma0Nine';if(portal.booting){root.innerHTML=portalLoading();return}if(!portal.configured||portal.connectionError){root.innerHTML=portalSetup();return}if(!portal.user||portal.recovery){root.innerHTML=portalAuth();return}if(!portal.profile){root.innerHTML=`<main class="portal-auth-wrap"><section class="portal-auth-card"><h1>We couldn’t open your profile.</h1>${portalInlineError(portal.error)}${portalButton('Try again','portalBoot()','renew',true)}${portalButton('Sign out','portalSignOut()','logout')}</section></main>`;return}if(portalWorkspaceMismatch()){root.innerHTML=portalWrongWorkspace();return}const admin=portalModeAdmin(),name=portal.profile.full_name;root.innerHTML=`<aside class="sidebar portal-sidebar ${portal.mobileOpen?'open':''}"><a class="brand" href="#policyportal" onclick="event.preventDefault();portalRoute('home')"><img src="sigma0nine-logo.png" alt="Sigma0Nine"></a><div class="portal-workspace"><span>${I(admin?'shield':'users')}</span><div><strong>${admin?'Admin workspace':'Partner workspace'}</strong><small>POLICY OPERATIONS</small></div></div><div class="navlabel">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${typeof portalNavHTML==='function'?portalNavHTML():portalButton('Overview',"portalRoute('home')",'grid')}</nav><div class="portal-sync-note">${I('renew')}Shared records<br><small>Live updates + 20-second refresh</small></div><div class="sidebarbottom"><button class="avatar" aria-label="Edit your profile" onclick="portalAccount()">${typeof portalAvatarHTML==='function'?portalAvatarHTML(name):portalInitial(name)}</button><div><strong>${pe(name)}</strong><small>${admin?'Administrator':'Partner'}</small></div><button class="quiet" aria-label="Sign out" onclick="portalSignOut()">${I('logout')}</button></div></aside>${portal.mobileOpen?'<button class="portal-mobile-backdrop" aria-label="Close menu" onclick="portalToggleNav()"></button>':''}<div class="shell"><header class="topbar"><div class="breadcrumb"><button class="quiet mobilemenu" aria-label="Toggle navigation" aria-expanded="${portal.mobileOpen||!portal.sidebarClosed}" onclick="portalToggleNav()">${I('menu')}</button><span>${admin?'Admin':'Partner'}</span><span>/</span><strong>${pe(typeof portalPageLabel==='function'?portalPageLabel():portal.view==='wallet'?'Wallet & credits':portal.view==='policies'?'Policies':'Overview')}</strong></div><div class="topright"><span class="portal-role">${admin?'ADMIN':'PARTNER'}</span><button class="quiet" aria-label="Refresh records" onclick="portalRefresh()">${I('renew')}</button><button class="avatar" aria-label="Your account" onclick="portalAccount()">${typeof portalAvatarHTML==='function'?portalAvatarHTML(name):portalInitial(name)}</button></div></header><main class="content portal-content">${portalInlineError(portal.error)}${typeof portalWorkspacePage==='function'?portalWorkspacePage():portal.view==='wallet'?portalWalletPage():portalOverviewPage()}<footer class="footer"><span>© 2026 Sigma0Nine · Your Insurance Business, Simplified.</span><span>${I('lock')}Private documents · Account-based access</span></footer></main></div>`;if(typeof businessStatus==='function')businessStatus();if(portal.view==='marketing'&&typeof loadAssetPreviews==='function')loadAssetPreviews()}
function portalToggleNav(){if(matchMedia('(max-width:600px)').matches)portal.mobileOpen=!portal.mobileOpen;else portal.sidebarClosed=!portal.sidebarClosed;portalRender()}
function portalAccount(){modal('Your account',`<h3>${pe(portal.profile.full_name)}</h3><p>${pe(portal.profile.email)}<br>${pe(portal.profile.phone||'')}</p><span class="badge">${pe(portal.profile.role)}</span><p class="subtle">Account ID: ${pe(portal.user.id)}</p><div class="modalfoot">${portalButton('Sign out','portalSignOut()','logout')}</div>`)}
function portalOverviewPage(){const admin=portalModeAdmin(),s=portal.summary;return heading(admin?'POLICY OPERATIONS':'YOUR PARTNER WORKSPACE',portal.view==='policies'?(admin?'Policy review queue':'My policies'):admin?'Every policy, accounted for.':'Your policies. Your progress.',admin?'Review uploaded documents, confirm decisions and credit the right partner.':'Upload a policy and track its review, earnings and payment receipt.',admin?portalButton('Upload for partner','portalUploadForm()','plus',true)+portalButton('Refresh queue','portalRefresh()','renew'):portalButton('Upload policy','portalUploadForm()','plus',true))+`${portal.view==='home'?`<div class="metrics">${metric('Policies submitted',s.total||0,'shield','Across your workspace')}${metric('Awaiting review',s.pending||0,'clock','Pending admin approval')}${metric('Approved policies',s.approved||0,'check','Reviewed and approved')}${metric(admin?'Credits issued':'Earned amount',admin?String(s.credited||0):PortalCore.money(s.amount_paise||0),'wallet',admin?'Exactly one credit per policy':'Confirmed earning credits')}</div>`:''}${!admin&&portal.view==='home'?`<section class="portal-progress-banner"><div>${I('shield')}<h2>Upload. Review. Reward.</h2><p>Your policy appears in the admin queue after upload. Credits appear here once an admin approves and awards them.</p></div><div class="portal-steps-mini"><span>1 · Upload</span><span>2 · Approval</span><span>3 · Credit</span></div></section>`:''}<section class="card portal-records"><div class="portal-records-head"><div><h2>${admin?'Policy submissions':'Your policy list'}</h2><p>${portal.loading?'Refreshing records…':`Showing up to ${portal.limit} latest records`}</p></div><span class="portal-live-indicator">${I('renew')}Auto-sync</span></div><div class="portal-filters"><div class="searchbox">${I('search')}<input aria-label="Search policies" placeholder="${admin?'Search partner, customer or policy…':'Search customer, insurer or policy…'}" value="${pe(portal.search)}" oninput="portal.search=this.value;portalUpdateList()"></div><select aria-label="Policy status" onchange="portal.status=this.value;portalUpdateList()">${['All','Pending','Approved','Rejected','Uploading'].map(v=>`<option value="${v}" ${portal.status===v?'selected':''}>${v==='Uploading'?'Upload incomplete':v}</option>`).join('')}</select></div><div id="portal-policy-list">${portalPolicyList()}</div>${portal.hasMore?`<div class="portal-load-more">${portalButton('Load more records','portal.limit+=50;portalRefresh()','plus')}</div>`:''}</section>`}
function portalVisiblePolicies(){return portal.policies.filter(p=>(portal.status==='All'?p.status!=='Uploading':p.status===portal.status)&&[p.customer_name,p.customer_mobile,p.policy_number,p.insurer,portalOwner(p).full_name,portalOwner(p).email].join(' ').toLowerCase().includes(portal.search.toLowerCase()))}
function portalUpdateList(){const list=document.querySelector('#portal-policy-list');if(list)list.innerHTML=portalPolicyList()}
function portalPolicyList(){const admin=portalModeAdmin(),rows=portalVisiblePolicies();if(!rows.length)return emptyCard(portal.loading?'Loading policies…':'No policies in this view',admin?'New partner submissions will appear here.':'Upload a policy copy to start your review process.',!admin?portalButton('Upload policy','portalUploadForm()','plus',true):'');return `<div class="tablewrap"><table><thead><tr>${admin?'<th>Partner account</th>':''}<th>Customer & policy</th><th>Product / premium</th><th>Submitted</th><th>Status</th><th>Credit</th><th>Action</th></tr></thead><tbody>${rows.map(p=>{const owner=portalOwner(p),credit=portalCreditFor(p);return `<tr>${admin?`<td><div class="person"><span class="initial">${portalInitial(owner.full_name)}</span><div><strong>${pe(owner.full_name)}</strong><small>${pe(owner.email)}</small></div></div></td>`:''}<td><strong>${pe(p.customer_name)}</strong><div class="subtle">${pe(p.customer_mobile)}<br>${pe(p.policy_number||'Policy number not entered')}</div></td><td>${pe(p.product)}<div class="subtle">${pe(p.insurer||'Insurer not entered')}<br>${PortalCore.money(p.premium_paise)}</div></td><td>${pe(portalDate(p.submitted_at||p.created_at))}</td><td>${portalStatus(p.status)}</td><td>${credit?`<strong>${PortalCore.money(credit.amount_paise)}</strong><div class="subtle">${portalPaymentFor(credit)?'Payment recorded':'Payment pending'}</div>`:p.status==='Approved'?'<span class="subtle">Awaiting credit</span>':'<span class="subtle">—</span>'}</td><td><div class="policy-row-actions">${portalButton('View',`portalPolicyDetails('${PortalCore.uuid(p.id)}')`,'file')}${admin&&p.status==='Approved'&&!credit?portalButton('Award earnings',`portalCreditForm('${p.id}')`,'wallet',true):admin&&credit?'<span class="badge">Credit issued</span>':''}</div></td></tr>`}).join('')}</tbody></table></div>`}

function portalUploadForm(){if(!portal.user)return portalRender();if(portalModeAdmin())return portalChooseUploadPartner();return portalRenderUploadForm(portal.profile)}
function portalRenderUploadForm(recipient){modal(portalModeAdmin()?'Upload policy for partner':'Upload a policy',`<div class="upload-recipient"><span class="eyebrow">POLICY OWNER & EARNINGS RECIPIENT</span><strong>${pe(recipient.full_name)}</strong><small>${pe(recipient.email)}</small>${portalModeAdmin()?portalButton('Change partner','portalChooseUploadPartner()','users'):''}</div><p>${portalModeAdmin()?'You are uploading on this partner’s behalf. The policy stays linked to their account and follows the approval process.':'Submit a private policy copy for admin review.'}</p><form id="portalUploadForm" data-owner-id="${pe(recipient.id)}" onsubmit="event.preventDefault();portalSubmitUpload(this)"><div class="formgrid"><label class="field full policy-upload-field">Policy copy *<span class="policy-file-picker"><input name="policyFile" type="file" aria-label="Choose policy document" onchange="policyAutoFill(this)" accept="application/pdf,image/png,image/jpeg,image/webp" required><span class="policy-upload-icon">${I('file')}</span><span class="policy-file-description"><strong data-policy-file-title>Choose policy document</strong><small>PDF, JPG, PNG or WebP · up to 10 MB</small></span><span class="policy-upload-action">Browse files</span></span><span class="subtle">Select a document to auto-fill the details below. A complete customer mobile is filled when available and can be edited.</span></label><div class="policy-extraction field full"><strong>Free document autofill</strong><span class="subtle">Automatic form filling · private on-device reading · review before submitting</span><p data-extraction-status role="status" aria-live="polite">Select a policy PDF or photo to suggest details automatically.</p><button type="button" data-extraction-stop hidden onclick="policyStopReading(this.form)">Stop reading & enter manually</button><label data-extraction-review hidden><input type="checkbox" name="extractionChecked"> I checked the auto-filled information against the policy.</label></div><label class="field">Customer name *<input name="customerName" required maxlength="150" autocomplete="off"></label><label class="field">Customer mobile *<input name="customerMobile" type="tel" required maxlength="16" inputmode="tel" autocomplete="off"></label><label class="field">Product *<select name="product" required>${optionsHTML(['Health','Motor','Life','Term','Travel','Group Health','Group PA','Home','Fire & Burglary','Jewellery Block','Other'],'',true)}</select></label><details class="field full policy-extra-details"><summary>Policy details · auto-filled when available <span>Review or edit</span></summary><div class="formgrid"><label class="field">Insurer<input name="insurer" maxlength="150"></label><label class="field">Policy number<input name="policyNumber" maxlength="120"></label><label class="field">Premium (₹)<input name="premium" type="number" min="0" max="1000000000" step="0.01" value="0"></label><label class="field">Start date<input name="startDate" type="date"></label><label class="field">Expiry date<input name="expiryDate" type="date"></label></div></details></div><div id="portal-upload-progress" role="status"></div><div id="portal-upload-error" role="alert"></div><div class="modalfoot"><button type="button" onclick="closeModal()">Cancel</button><button class="primary" type="submit">${I('shield')}Submit for review</button></div></form>`)}
async function portalSubmitUpload(form){
  if(form.policyReading)return toast('Wait for document reading, or choose manual entry.');
  if(form.elements.extractionChecked?.required&&!form.elements.extractionChecked.checked)return toast('Check the suggested details before submitting.');
  if(portal.busy)return;
  portal.busy=true;
  const button=form.querySelector('button[type=submit]'),errorNode=document.querySelector('#portal-upload-error'),progress=document.querySelector('#portal-upload-progress');
  button.disabled=true;errorNode.textContent='';
  try{
    if(!form.portalAttempt){
      const data=new FormData(form),file=form.elements.policyFile.files[0],extension=await PortalCore.validateFile(file);
      const mobile=PortalCore.phone(data.get('customerMobile')),premium=PortalCore.paise(data.get('premium')||'0'),name=String(data.get('customerName')||'').trim();
      if(!name||name.length>150)throw Error('Enter a valid customer name');
      const start=String(data.get('startDate')||''),expiry=String(data.get('expiryDate')||'');
      if(start&&expiry&&expiry<=start)throw Error('Expiry date must be after the start date');
      const ownerId=portalModeAdmin()?PortalCore.uuid(form.dataset.ownerId):portal.user.id;if(portalModeAdmin()&&!adminUpload.people.some(p=>p.id===ownerId&&p.role==='partner'))throw Error('Choose a valid partner account');const id=crypto.randomUUID(),path=ownerId+'/'+id+'/policy.'+extension;
      form.portalAttempt={file,created:false,record:{id,owner_id:ownerId,customer_name:name,customer_mobile:mobile,product:String(data.get('product')),insurer:String(data.get('insurer')||'').trim(),policy_number:String(data.get('policyNumber')||'').trim(),premium_paise:premium,start_date:start||null,expiry_date:expiry||null,original_file_name:file.name.slice(0,200),file_type:file.type,file_size:file.size,storage_path:path}};
    }
    await portalCompleteUpload(form.portalAttempt,progress);
    closeModal();portal.view='policies';portal.status='All';await portalRefresh();portalNotify('Policy submitted — awaiting admin review');
  }catch(e){
    progress.textContent='';errorNode.textContent=portalError(e)+(form.portalAttempt?' Retry will use this same submission. Incomplete uploads can also be finished from My policies.':'');
    if(form.portalAttempt){button.textContent='Retry same submission';for(const input of form.querySelectorAll('input,select'))input.disabled=true;await portalRefresh(true)}
  }finally{portal.busy=false;button.disabled=false}
}
async function portalCompleteUpload(attempt,progress){
  const r=attempt.record;
  progress.textContent='Checking your submission…';
  const existing=await portal.client.from('sigma_policies').select('id').eq('id',r.id).maybeSingle();
  if(existing.error)throw existing.error;
  if(!existing.data){const insert=await portal.client.from('sigma_policies').insert(r);if(insert.error)throw insert.error}
  attempt.created=true;
  let submit=await portal.client.rpc('sigma_submit_policy',{p_policy_id:r.id});
  if(!submit.error)return;
  if(!/Upload the policy document/i.test(submit.error.message))throw submit.error;
  progress.textContent='Uploading your private policy document…';
  const upload=await portal.client.storage.from('sigma-policies').upload(r.storage_path,attempt.file,{contentType:attempt.file.type,upsert:false,cacheControl:'0'});
  if(upload.error){const retry=await portal.client.rpc('sigma_submit_policy',{p_policy_id:r.id});if(!retry.error)return;throw upload.error}
  progress.textContent='Sending the policy to the admin queue…';
  submit=await portal.client.rpc('sigma_submit_policy',{p_policy_id:r.id});if(submit.error)throw submit.error;
}

async function portalPolicyDetails(id){PortalCore.uuid(id);let p=portal.policies.find(p=>p.id===id);if(!p)return;const owner=portalOwner(p),credit=portalCreditFor(p),admin=portalModeAdmin();modal('Policy details',`<div class="portal-detail-status">${portalStatus(p.status)}<span class="subtle">${pe(p.id.slice(0,8).toUpperCase())}</span></div><h3>${pe(p.customer_name)}</h3><dl class="review-list"><div><dt>Partner account</dt><dd>${pe(owner.full_name)}<br>${pe(owner.email)}</dd></div><div><dt>Uploaded by</dt><dd>${pe(portalUploaderName(p))}</dd></div><div><dt>Customer mobile</dt><dd>${pe(p.customer_mobile)}</dd></div><div><dt>Product / insurer</dt><dd>${pe(p.product)} · ${pe(p.insurer||'—')}</dd></div><div><dt>Policy number</dt><dd>${pe(p.policy_number||'—')}</dd></div><div><dt>Premium</dt><dd>${PortalCore.money(p.premium_paise)}</dd></div><div><dt>Period</dt><dd>${pe(p.start_date||'—')} to ${pe(p.expiry_date||'—')}</dd></div><div><dt>Document</dt><dd>${pe(p.original_file_name)}<br><span class="subtle">${(p.file_size/1024/1024).toFixed(2)} MB</span></dd></div><div><dt>Submitted</dt><dd>${pe(portalDate(p.submitted_at||p.created_at))}</dd></div>${p.reviewed_at?`<div><dt>Review</dt><dd>${pe(portalDate(p.reviewed_at))}<br>${pe(p.review_note||'')}</dd></div>`:''}${credit?`<div><dt>Account credit</dt><dd><strong>${PortalCore.money(credit.amount_paise)}</strong><br>${pe(credit.note||'')}<br>${pe(portalDate(credit.created_at))}</dd></div>`:''}</dl><div class="actions portal-detail-actions">${portalButton('Open policy copy',`portalDocument('${id}')`,'file')}${p.status==='Uploading'?portalButton('Finish submission',`portalFinishUpload('${id}')`,'renew',true):''}${admin&&p.status==='Pending'?portalButton('Approve',`portalReviewForm('${id}','Approved')`,'check',true)+portalButton('Reject',`portalReviewForm('${id}','Rejected')`,'close'):''}${admin&&p.status==='Approved'&&!credit?portalButton('Award earnings',`portalCreditForm('${id}')`,'wallet',true):''}</div>${credit?portalPaymentDetails(credit):''}<div id="portal-document-link"></div><div id="portal-action-error" role="alert"></div>`)}
async function portalDocument(id){try{let p=portal.policies.find(p=>p.id===PortalCore.uuid(id));if(!p)return;const {data,error}=await portal.client.storage.from('sigma-policies').createSignedUrl(p.storage_path,60,{download:p.original_file_name});if(error)throw error;document.querySelector('#portal-document-link').innerHTML=`<div class="portal-document-ready"><p>Private download link · expires in 60 seconds</p><a href="${pe(data.signedUrl)}" target="_blank" rel="noopener noreferrer">${I('download')}Download ${pe(p.original_file_name)}</a></div>`}catch(e){document.querySelector('#portal-action-error').textContent=portalError(e)}}
function portalReviewForm(id,decision){if(!portalModeAdmin())return;const p=portal.policies.find(p=>p.id===PortalCore.uuid(id));modal(decision==='Approved'?'Approve policy':'Reject policy',`<p><strong>${pe(p.customer_name)}</strong> · ${pe(p.product)}<br>Partner account: ${pe(portalOwner(p).full_name)} (${pe(portalOwner(p).email)})</p><p>${decision==='Approved'?'Confirm that you have reviewed the uploaded policy. You can award an earning amount after approval.':'Give the partner a clear reason for rejection.'}</p><form onsubmit="event.preventDefault();portalReviewSubmit('${id}','${decision}',this)"><label class="field">${decision==='Rejected'?'Rejection reason *':'Review note'}<textarea name="note" rows="3" maxlength="2000" ${decision==='Rejected'?'required minlength="5"':''}></textarea></label><div class="portal-form-error" role="alert"></div><div class="modalfoot"><button type="button" onclick="portalPolicyDetails('${id}')">Back</button><button type="submit" class="primary">${decision==='Approved'?'Confirm approval':'Confirm rejection'}</button></div></form>`)}
async function portalReviewSubmit(id,decision,form){if(portal.busy)return;portal.busy=true;const button=form.querySelector('button[type=submit]');button.disabled=true;try{const result=await portal.client.rpc('sigma_review_policy',{p_policy_id:PortalCore.uuid(id),p_decision:decision,p_note:new FormData(form).get('note')||''});if(result.error)throw result.error;closeModal();await portalRefresh();if(decision==='Approved'){portalNotify('Policy approved — enter the partner earning amount below.');portalCreditForm(id)}else portalNotify('Policy rejected — the partner can see your reason.')}catch(e){form.querySelector('.portal-form-error').textContent=portalError(e)}finally{portal.busy=false;button.disabled=false}}
let portalPendingCredit=null;
async function portalConfirmCredit(button){if(portal.busy||!portalPendingCredit)return;portal.busy=true;button.disabled=true;try{const p=portalPendingCredit,result=await portal.client.rpc('sigma_credit_policy',{p_policy_id:p.policyId,p_points:p.points,p_amount_paise:p.amount_paise,p_note:p.note});if(result.error)throw result.error;portalPendingCredit=null;closeModal();await portalRefresh();portalNotify('Earning amount awarded');portalPolicyDetails(p.policyId)}catch(e){document.querySelector('#portal-credit-error').textContent=portalError(e);await portalRefresh(true)}finally{portal.busy=false;button.disabled=false}}
async function portalFinishUpload(id){const p=portal.policies.find(p=>p.id===PortalCore.uuid(id));try{const result=await portal.client.rpc('sigma_submit_policy',{p_policy_id:id});if(result.error)throw result.error;closeModal();await portalRefresh();portalNotify('Policy submitted for review')}catch(e){if(/Upload the policy document/i.test(e.message)){modal('Resume policy upload',`<p>Choose the original file: <strong>${pe(p.original_file_name)}</strong></p><form onsubmit="event.preventDefault();portalResumeUpload('${id}',this)"><label class="field">Original policy copy<input type="file" name="policyFile" required accept="${pe(p.file_type)}"></label><div class="portal-form-error" role="alert"></div><div class="modalfoot"><button class="primary" type="submit">Upload & submit</button></div></form>`)}else document.querySelector('#portal-action-error').textContent=portalError(e)}}
async function portalResumeUpload(id,form){if(portal.busy)return;portal.busy=true;const button=form.querySelector('button[type=submit]');button.disabled=true;try{let p=portal.policies.find(p=>p.id===id),file=form.elements.policyFile.files[0];await PortalCore.validateFile(file);if(file.name!==p.original_file_name||file.size!==Number(p.file_size)||file.type!==p.file_type)throw Error('Choose the same original file recorded for this submission');let upload=await portal.client.storage.from('sigma-policies').upload(p.storage_path,file,{contentType:file.type,upsert:false,cacheControl:'0'});if(upload.error)throw upload.error;let submit=await portal.client.rpc('sigma_submit_policy',{p_policy_id:id});if(submit.error)throw submit.error;closeModal();await portalRefresh();portalNotify('Policy submitted for review')}catch(e){form.querySelector('.portal-form-error').textContent=portalError(e)}finally{portal.busy=false;button.disabled=false}}

window.addEventListener('DOMContentLoaded',portalBoot);
window.addEventListener('hashchange',()=>{if(!portal.configured)return;const hash=location.hash.slice(1);if(hash.startsWith('admin')&&portalEntry.role!=='admin'){location.assign('/admin#'+hash);return}if(['partner','mypolicies','wallet'].includes(hash)&&portalEntry.role==='admin'){location.assign('/partner#'+hash);return}portal.view=typeof portalBusinessRoute==='function'?portalBusinessRoute():['wallet','admin-ledger'].includes(hash)?'wallet':['mypolicies','admin-policies'].includes(hash)?'policies':'home';portalRender()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&portal.user)portalRefresh(true)});
